function compute(inputs){
  var n = Math.round(inputs.n), w = inputs.w.slice(0, n);
  var s = 0; for (var i = 0; i < n; i++) s += w[i];
  if (!(s > 0)) return {H: null, Hmax: null, p: null, contrib: null, warning: 'All weights are zero: no valid distribution.'};
  var lg = inputs.unit === 'bits' ? Math.log(2) : 1;
  var p = w.map(function(v){ return v / s; });
  var c = p.map(function(q){ return q > 0 ? -q * Math.log(q) / lg : 0; });
  var H = c.reduce(function(a, b){ return a + b; }, 0);
  var Hmax = Math.log(n) / lg;
  var u = inputs.unit;
  var msg = H < 1e-12 ? 'One outcome is certain: no uncertainty, H = 0.' : (Math.abs(H - Hmax) < 1e-9 ? 'All outcomes equally likely: H is at its maximum log(n).' : 'H = ' + H.toFixed(3) + ' ' + u + ', below the maximum ' + Hmax.toFixed(3) + ' ' + u + '.');
  return {H: H, Hmax: Hmax, p: p, contrib: c, insight: msg};
}
